from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        spy_security = self.AddEquity("SPY", Resolution.Minute)
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        option_security.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )
        self.option_symbol = option_security.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol, self.consolidator
        )

        self.closes = []
        self.pending_signal = None

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.blocked_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        if len(self.closes) >= 20:
            previous_fast = sum(self.closes[-5:]) / 5.0
            previous_slow = sum(self.closes[-20:]) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(bar.Close))
        if len(self.closes) > 20:
            self.closes.pop(0)

        if len(self.closes) < 20:
            return

        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        bar_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (
            eligible_time
            and previous_fast is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
            and self.held_symbol is None
            and not self._entry_order_open()
        ):
            self.pending_signal = (bar.EndTime, float(bar.Close))

    def OnData(self, slice):
        current_date = self.Time.date()

        self._process_expiration(current_date)
        self._process_time_stop(current_date)
        self._process_profit_target(slice)

        if self.pending_signal is None:
            return

        signal_time, spy_price = self.pending_signal
        self.pending_signal = None

        if current_date == self.blocked_entry_date:
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        chain = None
        try:
            chain = slice.OptionChains.get(self.option_symbol)
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        contracts = list(chain)

        eligible_expiries = [
            self._expiration_date(contract)
            for contract in contracts
            if self._expiration_date(contract) >= minimum_expiry
        ]

        if not eligible_expiries:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiry = min(eligible_expiries)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if (
                self._expiration_date(contract) == selected_expiry
                and contract.Right == OptionRight.Call
                and float(contract.Strike) >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        selected_contract = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected_contract.Symbol, 1)

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Call exit filled: {}".format(order_event.Symbol))
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.exit_ticket = None

            message = str(order_event.Message).lower()
            if "exercise" in message or "assignment" in message:
                self.Debug("Unexpected exercise or assignment handling required.")

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            "Unexpected option exercise or assignment: {}".format(
                assignment_event.Symbol
            )
        )
        self.blocked_entry_date = self.Time.date()

    def _process_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._exit_order_open():
            return

        quote = None
        try:
            quote = slice.QuoteBars.get(self.held_symbol)
        except Exception:
            quote = None

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_time_stop(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self._expiration_date_from_symbol(self.held_symbol)
        preceding_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.blocked_entry_date = current_date
            if not self._exit_order_open():
                self._submit_exit("expiration time stop")

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self._expiration_date_from_symbol(self.held_symbol)
        if current_date >= expiry_date:
            self.blocked_entry_date = current_date
            if not self._exit_order_open():
                self._submit_exit("expiration safeguard")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Call exit submitted: {}".format(reason))

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted,
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted,
        )

    def _expiration_date(self, contract):
        return contract.Expiry.date()

    def _expiration_date_from_symbol(self, symbol):
        return symbol.ID.Date.date()

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

